queries.item:
INSERT INTO ?:payment_processors (processor, processor_script, processor_template, admin_template, callback, type, addon)
SELECT 'NETOPIA Payments', 'netopia_payments.php', 'views/orders/components/payments/cc_outside.tpl', 'netopia_payments.tpl', 'N', 'P', 'netopia_payments'
FROM (SELECT 1) AS placeholder
WHERE NOT EXISTS (
    SELECT 1 FROM ?:payment_processors WHERE processor_script = 'netopia_payments.php'
);

